import { isFeatureEnabled, type FlagKey } from "./flags";

export type User = {
  id: string;
  email: string;
  name: string;
  createdAt: string;
};

const users: User[] = [
  { id: "1", email: "ada@example.com", name: "Ada", createdAt: "2026-01-04" },
  { id: "2", email: "grace@example.com", name: "Grace", createdAt: "2026-02-11" },
];

export async function listUsers(): Promise<User[]> {
  return users;
}

export async function getUser(id: string): Promise<User | undefined> {
  return users.find((u) => u.id === id);
}

// TODO: there is no real session handling yet — the dashboard just picks the first user.
export async function getCurrentUser(): Promise<User | undefined> {
  return users[0];
}

/** Evaluate a feature flag for a specific user id. */
export async function isFeatureEnabledForUser(
  userId: string,
  flag: FlagKey
): Promise<boolean> {
  const user = await getUser(userId);
  return isFeatureEnabled(flag, user);
}

/** Evaluate a feature flag for whoever is currently signed in. */
export async function isFeatureEnabledForCurrentUser(
  flag: FlagKey
): Promise<boolean> {
  const user = await getCurrentUser();
  return isFeatureEnabled(flag, user);
}

